		Scanner sc = new Scanner(System.in);
		int a = sc.nextInt();
		int b = sc.nextInt();

		if (a<b) {
			int temp = a;
			a = b;
			b = temp;
		}

		int c = gcd(a,b);
		System.out.println(c);


	}

	public static int gcd(int n1, int n2){
		if (n1 == 0) {
			return n2;
		}
		if (n1 == n2) {
			return n1;
		}
		return gcd(n2%n1, n1);
	}
}

import java.util.*;
import java.lang.Math.*;

public class Main{
	private static final Scanner scan = new Scanner(System.in);

	public static void main(String[] args){

		int x = scan.nextInt();
		int y = scan.nextInt();
		int gcd;
		gcd = gcd(x, y);
		System.out.println(gcd);
	}

	public static int gcd(int x, int  y){
		int r;
		if(x < y)swap(x, y);
		while(y > 0){
			r = x % y;
			x = y;
			y = r;
		}
		return x;
	}

	public static int gcdB(int x, int y){
		int n = min(x, y);
		for(int d = n; d > 0; d--){
			if((x % d == 0) && (y % d == 0)){
				return d;
			}
		}
	}
}

