		int b=Integer.parseInt((String)stk.nextElement());
		System.out.println(yakusuu(a,b));
	}
	static int yakusuu(int a,int b){
		if(a>b){int tmp=a;
		a=b;
		b=tmp;
		}
		int t=0;
		for(int i=a;i>0;--i){
			if((a%i)==0&&(b%i)==0){t=i;break;}
		}
		return t;
	}

}

