				}
			}
		}
		System.out.println(max);
	}

	static ArrayList<Integer> Divisor(long x){
		ArrayList<Integer> Divisor = new ArrayList<Integer>();
		for(int d = 1; d <= x; d++){
			if(Math.floorMod(x, d) == 0){
				Divisor.add(d);
			}
		}
		return Divisor;
	}
}

